CREATE TABLE input_pause_audit(value integer);
CREATE FUNCTION retained_input(value integer) RETURNS integer LANGUAGE sql VOLATILE AS 'INSERT INTO input_pause_audit VALUES ($1); SELECT $1';
CREATE FUNCTION retained_pair(first_arg integer,second_arg integer) RETURNS integer LANGUAGE sql VOLATILE AS 'INSERT INTO input_pause_audit VALUES ($1+$2); SELECT $1+$2';
CREATE FUNCTION retained_defaults(first_arg integer DEFAULT set_config('application_name',(current_setting('application_name')::integer+1)::text,false)::integer,second_arg integer DEFAULT retained_input(7)) RETURNS integer LANGUAGE sql VOLATILE AS 'INSERT INTO input_pause_audit VALUES ($1+$2); SELECT $1+$2';
CREATE FUNCTION retained_variadic(marker integer,VARIADIC members integer[]) RETURNS integer LANGUAGE sql VOLATILE AS 'INSERT INTO input_pause_audit VALUES ($1+$2[1]+$2[2]); SELECT $1+$2[1]+$2[2]';
CREATE FUNCTION retained_rows(value integer) RETURNS TABLE(result integer) LANGUAGE sql VOLATILE AS 'INSERT INTO input_pause_audit VALUES ($1); SELECT $1 UNION ALL SELECT $1+1';
CREATE FUNCTION retained_procedural(value integer) RETURNS integer LANGUAGE plpgsql VOLATILE AS 'BEGIN INSERT INTO input_pause_audit VALUES (value); RETURN value; END';
