CREATE FUNCTION retained_replace_argument() RETURNS integer LANGUAGE plpgsql AS $$BEGIN EXECUTE 'CREATE OR REPLACE FUNCTION retained_defaults(first_arg integer DEFAULT 50,second_arg integer DEFAULT retained_input(99)) RETURNS integer LANGUAGE sql VOLATILE AS ''INSERT INTO input_pause_audit VALUES ($1+$2+100); SELECT $1+$2+100'''; RETURN 1; END$$;
SELECT set_config('application_name','0',false);
SELECT retained_defaults(retained_replace_argument());
SELECT current_setting('application_name');
SELECT value FROM input_pause_audit ORDER BY value;
TRUNCATE input_pause_audit;
CREATE FUNCTION retained_reclassify() RETURNS integer LANGUAGE plpgsql AS $$BEGIN EXECUTE 'CREATE OR REPLACE FUNCTION retained_pair(first_arg integer,second_arg integer) RETURNS integer LANGUAGE sql IMMUTABLE AS ''SELECT $1+$2'''; RETURN 1; END$$;
SELECT retained_variadic(retained_reclassify(),retained_pair(1,2),retained_input(7));
